#include <iostream>
#include <string>
#include <utility>  // For std::move

class ZooAnimal {
private:
    std::string name;  // Resource: a string that owns memory

public:
    ZooAnimal(const std::string& n) : name(n) {}  // Constructor
    ZooAnimal(ZooAnimal&& other) noexcept : name(std::move(other.name)) {
        // Move constructor: Transfer ownership of 'name' from 'other'
        std::cout << "Move constructor called for " << name << std::endl;
    }
    ZooAnimal& operator=(ZooAnimal&& other) noexcept {
        if (this != &other) {
            name = std::move(other.name);  // Move assignment
            std::cout << "Move assignment called for " << name << std::endl;
        }
        return *this;
    }
    ~ZooAnimal() { std::cout << "Destructor called for " << name << std::endl; }
    const std::string& getName() const { return name; }
};

int main() {
    ZooAnimal bear("Bear");  // Creates a ZooAnimal object
    ZooAnimal anotherBear(std::move(bear));  // Moves resources from 'bear' to 'anotherBear'
    std::cout << "After move, original bear name: " << bear.getName() << std::endl;  // Moved-from object is in a valid but unspecified state
    return 0;
}
